    static let marker = "<!-- LUMEN_GROUNDING_V1 -->"
    private static let sectionHeaders = ["[LOCAL MEMORY]", "[LOCAL SOURCES]", "[AVAILABLE LOCAL TOOLS]", "[RUNTIME POLICY]"]

    static func sectionOccurrenceCounts(_ text: String) -> [String: Int] {
        var out: [String: Int] = [:]
